'use client'

import { useId, useState, type ReactNode } from 'react'
import './project-preview-list.css'

export interface ProjectPreviewListItem {
  id: string
  title: string
  category: string
  href: string
  year?: string
  /** Decorative artwork. The title and category provide the accessible description. */
  media: ReactNode
}

export interface ProjectPreviewListProps {
  items: ProjectPreviewListItem[]
  title?: string
  className?: string
}

function decorativeMedia(element: HTMLDivElement | null) {
  element?.setAttribute('inert', '')
}

export function ProjectPreviewList({ items, title = 'Project index', className = '' }: ProjectPreviewListProps) {
  const headingId = useId()
  const [previewId, setPreviewId] = useState<string | null>(null)
  const preview = items.find((item) => item.id === previewId) ?? items[0]

  return (
    <section className={`ac-project-preview-list ${className}`.trim()} aria-labelledby={headingId}>
      <header className="ac-project-preview-heading"><h2 id={headingId}>{title}</h2><span>{items.length.toString().padStart(2, '0')} projects</span></header>
      {items.length > 0 ? (
        <div className="ac-project-preview-layout">
          <ol className="ac-project-preview-rows">
            {items.map((item, index) => (
              <li key={item.id}>
                <a
                  className="ac-project-preview-link"
                  href={item.href}
                  data-previewing={preview?.id === item.id ? 'true' : undefined}
                  onPointerEnter={(event) => { if (event.pointerType !== 'touch') setPreviewId(item.id) }}
                  onFocus={() => setPreviewId(item.id)}
                >
                  <span className="ac-project-preview-number" aria-hidden="true">{(index + 1).toString().padStart(2, '0')}</span>
                  <div ref={decorativeMedia} className="ac-project-preview-thumbnail" aria-hidden="true">{item.media}</div>
                  <div className="ac-project-preview-copy"><h3>{item.title}</h3><span>{item.category}{item.year && <> · {item.year}</>}</span></div>
                  <span className="ac-project-preview-arrow" aria-hidden="true">↗</span>
                </a>
              </li>
            ))}
          </ol>
          <div ref={decorativeMedia} className="ac-project-preview-art" aria-hidden="true">
            <div key={preview.id} className="ac-project-preview-image">{preview.media}</div>
            <div className="ac-project-preview-caption"><span>{preview.title}</span><span>{preview.category}</span></div>
          </div>
        </div>
      ) : <p className="ac-project-preview-empty">Projects are on the way. Check back soon.</p>}
    </section>
  )
}

.ac-project-preview-list{--ac-preview-ink:var(--ac-preview-theme-ink, #252820);--ac-preview-muted:var(--ac-preview-theme-muted, #77796f);--ac-preview-line:var(--ac-preview-theme-line, #d6d7cd);--ac-preview-accent:#e25434;--ac-preview-radius:4px;container-type:inline-size;width:100%;font-family:inherit;color:var(--ac-preview-ink);font-size:14px}
.ac-project-preview-list *{box-sizing:border-box}
.ac-project-preview-heading{display:flex;justify-content:space-between;align-items:baseline;gap:18px;margin-bottom:24px}
.ac-project-preview-heading h2{margin:0;font-size:clamp(26px,5cqw,44px);font-weight:500;letter-spacing:-.055em;line-height:1.05}
.ac-project-preview-heading>span{flex-shrink:0;font-size:10px;color:var(--ac-preview-muted);font-variant-numeric:tabular-nums}
.ac-project-preview-layout{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,1fr);gap:30px;align-items:start}
.ac-project-preview-rows{list-style:none;margin:0;padding:0;border-top:1px solid var(--ac-preview-line)}
.ac-project-preview-rows>li{margin:0;border-bottom:1px solid var(--ac-preview-line)}
.ac-project-preview-link{display:grid;grid-template-columns:22px minmax(0,1fr) 25px;align-items:center;gap:12px;min-height:98px;padding:20px 2px;text-decoration:none;color:inherit;transition:color .2s}
.ac-project-preview-number{font-size:10px;color:var(--ac-preview-muted);align-self:start;padding-top:4px;font-variant-numeric:tabular-nums}
.ac-project-preview-copy h3{margin:0 0 7px;font-weight:500;font-size:clamp(22px,4cqw,34px);line-height:1;letter-spacing:-.05em;overflow-wrap:anywhere}
.ac-project-preview-copy>span{color:var(--ac-preview-muted);font-size:10px;line-height:1.4}
.ac-project-preview-arrow{justify-self:end;font-size:24px;transition:transform .25s}
.ac-project-preview-link[data-previewing=true]{color:var(--ac-preview-accent)}
.ac-project-preview-link[data-previewing=true] .ac-project-preview-arrow{transform:translate(2px,-2px)}
.ac-project-preview-link:focus-visible{outline:2px solid var(--ac-preview-accent);outline-offset:5px}
.ac-project-preview-thumbnail{display:none;pointer-events:none}
.ac-project-preview-art{overflow:hidden;position:sticky;top:16px;border-radius:var(--ac-preview-radius);background:var(--ac-preview-media-background,var(--ac-preview-theme-card, #e5e7d9));pointer-events:none}
.ac-project-preview-image{aspect-ratio:4/5;overflow:hidden;animation:ac-project-preview-arrive .3s ease-out both}
.ac-project-preview-image>*{display:block;width:100%;height:100%;object-fit:cover}
.ac-project-preview-caption{display:flex;justify-content:space-between;gap:12px;padding:12px 13px;font-size:10px;background:var(--ac-preview-caption-background,var(--ac-preview-theme-stage, #eeeeE6));color:var(--ac-preview-ink)}
.ac-project-preview-caption span:last-child{color:var(--ac-preview-muted)}
.ac-project-preview-empty{margin:0;padding:36px 0;border-top:1px solid var(--ac-preview-line);color:var(--ac-preview-muted);line-height:1.6}
@container(max-width:500px){.ac-project-preview-layout{grid-template-columns:minmax(0,1fr);gap:0}.ac-project-preview-art{display:none}.ac-project-preview-link{grid-template-columns:18px 66px minmax(0,1fr) 22px;gap:12px;padding-block:15px;min-height:96px}.ac-project-preview-thumbnail{display:block;overflow:hidden;aspect-ratio:1;border-radius:var(--ac-preview-radius);background:var(--ac-preview-media-background,var(--ac-preview-theme-card, #e5e7d9))}.ac-project-preview-thumbnail>*{display:block;width:100%;height:100%;object-fit:cover}.ac-project-preview-copy h3{font-size:25px}.ac-project-preview-heading{margin-bottom:20px}.ac-project-preview-number{align-self:center;padding-top:0}}
@container(max-width:300px){.ac-project-preview-link{grid-template-columns:15px 52px minmax(0,1fr) 18px;gap:8px}.ac-project-preview-copy h3{font-size:21px}.ac-project-preview-copy>span{font-size:9px}.ac-project-preview-arrow{font-size:20px}}
@keyframes ac-project-preview-arrive{from{opacity:.35;transform:scale(1.025)}to{opacity:1;transform:scale(1)}}
@media(prefers-reduced-motion:reduce){.ac-project-preview-image{animation:none}.ac-project-preview-link,.ac-project-preview-arrow{transition:none}}

/* Neutral surfaces follow an explicit page theme; artwork and accents keep their palette. */
:where([data-theme="light"]) .ac-project-preview-list {
  --ac-preview-theme-card: #ffffff;
  --ac-preview-theme-ink: #202722;
  --ac-preview-theme-line: #d7ded4;
  --ac-preview-theme-muted: #687269;
  --ac-preview-theme-stage: #eff2ec;
  color-scheme: light;
}
:where([data-theme="dark"], .dark) .ac-project-preview-list {
  --ac-preview-theme-card: #242c26;
  --ac-preview-theme-ink: #edf2eb;
  --ac-preview-theme-line: #3d483e;
  --ac-preview-theme-muted: #a7b3a3;
  --ac-preview-theme-stage: #202822;
  color-scheme: dark;
}
